import{_ as a}from"./chunks/backup.9Coub0cd.js";import{_ as t,o,c as r,a2 as s}from"./chunks/framework.DSc8fo6x.js";const g=JSON.parse('{"title":"Backup and restore","description":"","frontmatter":{},"headers":[],"relativePath":"en/backup.md","filePath":"en/backup.md"}'),n={name:"en/backup.md"};function l(i,e,c,d,h,p){return o(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="backup-and-restore" tabindex="-1">Backup and restore <a class="header-anchor" href="#backup-and-restore" aria-label="Permalink to &quot;Backup and restore&quot;">​</a></h1><p><img src="'+a+'" alt="Backup"></p><h2 id="the-program-backs-up-by-itself" tabindex="-1">The program backs up by itself <a class="header-anchor" href="#the-program-backs-up-by-itself" aria-label="Permalink to &quot;The program backs up by itself&quot;">​</a></h2><ul><li>Regularly (usually every 20 hours) and <strong>when it closes</strong>.</li><li>A separate backup before an update and before a restore.</li><li>If <a href="./telegram.html">Telegram</a> is connected — once a day to your phone.</li></ul><h2 id="once-a-week-usb" tabindex="-1">Once a week: USB <a class="header-anchor" href="#once-a-week-usb" aria-label="Permalink to &quot;Once a week: USB&quot;">​</a></h2><p>Insert a USB stick → <strong>Backup</strong> → <strong>Copy the latest backup to …</strong>. Do not keep the USB stick next to the computer.</p><h2 id="recovery-code" tabindex="-1">Recovery code <a class="header-anchor" href="#recovery-code" aria-label="Permalink to &quot;Recovery code&quot;">​</a></h2><p><strong>Backup → Recovery code</strong> → your password. It must be written on paper — if the computer breaks, the data cannot be brought back without it.</p><h2 id="restoring-a-backup" tabindex="-1">Restoring a backup <a class="header-anchor" href="#restoring-a-backup" aria-label="Permalink to &quot;Restoring a backup&quot;">​</a></h2><p>If something got messed up by mistake:</p><ul><li>in the list, <strong>Restore</strong> next to the backup → admin password.</li></ul><h3 id="fayldan-berpa" tabindex="-1">Restore from file <a class="header-anchor" href="#fayldan-berpa" aria-label="Permalink to &quot;Restore from file {#fayldan-berpa}&quot;">​</a></h3><p>A file from USB or downloaded from Telegram: <strong>Restore from file</strong> → choose the file → admin password.</p><ul><li><strong>If Telegram sent parts (<code>.001</code>, <code>.002</code>…)</strong> — download all of them and select <strong>all together</strong> (hold Ctrl).</li><li>If the file is from another computer, also enter that installation&#39;s <strong>recovery code</strong>.</li></ul><p>After a restore everyone logs in again. The state before the restore is kept as a &quot;Before restore&quot; backup — nothing is lost.</p><h2 id="berpa-ekrani" tabindex="-1">Recovery screen <a class="header-anchor" href="#berpa-ekrani" aria-label="Permalink to &quot;Recovery screen {#berpa-ekrani}&quot;">​</a></h2><p>If the database is deleted or damaged, the key is lost, or an old version of the program is installed, the <strong>Recovery</strong> screen opens instead of the normal one. The reason is written at the top.</p><ol><li>Enter the <strong>recovery code</strong> (from the paper).</li><li>Choose: <strong>Restore this backup</strong>, <strong>Restore from file</strong> (USB, Telegram), <strong>Recover key</strong> or <strong>Check again</strong>.</li><li><strong>Start with an empty database</strong> — only if there are no backups at all.</li></ol><p>Nothing can be done on this screen without the recovery code — the data is protected. If it says &quot;Old program version&quot;, just install the latest version.</p><h2 id="warning-the-database-was-replaced-with-an-old-copy" tabindex="-1">&quot;WARNING: the database was replaced with an old copy!&quot; <a class="header-anchor" href="#warning-the-database-was-replaced-with-an-old-copy" aria-label="Permalink to &quot;&quot;WARNING: the database was replaced with an old copy!&quot;&quot;">​</a></h2><p>While the program was closed, someone replaced the data file with an old copy — sales made in between may be missing. Check the backups in Telegram and on USB, restore a newer one if needed, then press <strong>Got it</strong>.</p><h2 id="komputer-xarab-oldu" tabindex="-1">The computer broke <a class="header-anchor" href="#komputer-xarab-oldu" aria-label="Permalink to &quot;The computer broke {#komputer-xarab-oldu}&quot;">​</a></h2><p>Install Kassa on the new computer → create a temporary admin on first launch → <strong>Backup → Restore from file</strong> (USB or Telegram file) + the old installation&#39;s <strong>recovery code</strong>. The old users, products and settings come back.</p>',23)])])}const m=t(n,[["render",l]]);export{g as __pageData,m as default};
